      "lessonGoal": "Yêu cầu cần đạt:\nBy the end of this unit, students will be able to:\n• pronounce common three-syllable nouns with correct stress;\n• understand and use words and phrases related to inventions;\n• use the present perfect, gerunds, and to-infinitives correctly;\n• read for main ideas and specific information in a text about an\ninvention;\n• talk about inventions and their uses;\n• listen to instructions on how to use an invention for specific\ninformation;\n• write about the benefits of an invention;\n• make and respond to requests;\n• understand computer hardware;\n• collect information about an existing invention for the classroom or creat a new one and give a group presentation about it.\nNăng lực số:\n6.1NC1a: Phân tích được cách AI/công nghệ hoạt động trong các ứng dụng cụ thể.\nNăng lực AI:\nC3. Công nghệ AI (Một số công nghệ trong AI) và D2. Cấu trúc & tương tác, cải tiến hệ thống (Hệ thống AI)",
