      "yccd": "By the end of this unit, students will be able to:\n• use rising and falling intonation in question tags;\n• understand and use words and phrases related to ecosystems;\n• understand and use compound nouns;\n• read for main ideas and specific information in an article about a national park;\n• talk about ways to protect local biodiversity and respond to situations that may harm the environment;\n• listen for specific information in a talk about the human impact on ecosystems, and make predictions;\n• write an opinion essay about spending money on restoring local ecosystems;\n• express likes and dislikes;\n• understand how ecosystems around the world are protected and\nrestored;\n• design a poster about a local ecosystem and how to restore/protect it, and present it to the class.",
      "lessonGoal": "Yêu cầu cần đạt:\nBy the end of this unit, students will be able to:\n• use rising and falling intonation in question tags;\n• understand and use words and phrases related to ecosystems;\n• understand and use compound nouns;\n• read for main ideas and specific information in an article about a national park;\n• talk about ways to protect local biodiversity and respond to situations that may harm the environment;\n• listen for specific information in a talk about the human impact on ecosystems, and make predictions;\n• write an opinion essay about spending money on restoring local ecosystems;\n• express likes and dislikes;\n• understand how ecosystems around the world are protected and\nrestored;\n• design a poster about a local ecosystem and how to restore/protect it, and present it to the class.\nNăng lực số:\n4.4NC1a: Trình bày được các cách thức khác nhau để bảo vệ môi trường (kết hợp công nghệ).\nNăng lực AI:\nA2. Bền vững và công bằng",
      "objectivesKnowledge": "By the end of this unit, students will be able to:\n• use rising and falling intonation in question tags;\n• understand and use words and phrases related to ecosystems;\n• understand and use compound nouns;\n• read for main ideas and specific information in an article about a national park;\n• talk about ways to protect local biodiversity and respond to situations that may harm the environment;\n• listen for specific information in a talk about the human impact on ecosystems, and make predictions;\n• write an opinion essay about spending money on restoring local ecosystems;\n• express likes and dislikes;\n• understand how ecosystems around the world are protected and\nrestored;\n• design a poster about a local ecosystem and how to restore/protect it, and present it to the class.",
      "objectivesCompetency": "Năng lực số:\n4.4NC1a: Trình bày được các cách thức khác nhau để bảo vệ môi trường (kết hợp công nghệ).\nNăng lực AI:\nA2. Bền vững và công bằng",
