      "yccd": "Review 3 is aimed at revising the language and skills Ss have learnt in Units 6–8, and providing exam practice by following question formats used in the National Upper-secondary School Exam Paper.\nThe review can be taught in three lessons, e.g. 1: Language, 2: Listening and speaking skills, 3: Reading and writing skills. Teachers can also choose to give some activities for homework and spend less time on the review in class.\nIntroduce the review by asking Ss if they remember what they have learnt so far in terms of language and skills. Summarise Ss’ answers and add some more information if necessary.",
